+export interface PaginationResult<T> {
+  items: T[];
+  page: number;
+  pageSize: number;
+  totalPages: number;
+  totalItems: number;
+  hasNext: boolean;
+  hasPrev: boolean;
+}
+
+export function paginate<T>(
+  data: T[],
+  page: number,
+  pageSize: number
+): PaginationResult<T> {
+  if (page < 1) {
+    page = 1;
+  }
+
+  if (pageSize < 1) {
+    pageSize = 10;
+  }
+
+  var totalItems = data.length;
+  var totalPages = Math.ceil(totalItems / pageSize);
+  var startIndex = (page - 1) * pageSize;
+  var items: T[] = [];
+
+  for (var i = startIndex; i <= startIndex + pageSize; i++) {
+    if (i < totalItems) {
+      items.push(data[i]);
+    }
+  }
+
+  return {
+    items,
+    page,
+    pageSize,
+    totalPages,
+    totalItems,
+    hasNext: page < totalPages,
+    hasPrev: page > 1,
+  };
+}
